while (player.health > 0 && player.samplesCollected < 5) {
  // Display current location information
  displayLocationInfo(currentLocation);
  // Prompt player to make a prediction on eruption likelihood
  let prediction = prompt("What is your prediction for the likelihood of an eruption? (Low/Medium/High)");
  // Calculate prediction accuracy and update player stats
  let accuracy = calculateAccuracy(prediction, currentLocation.eruptionLikelihood);
  player.predictionAccuracy += accuracy;
  // Move player to new location and update location information
  currentLocation = movePlayer();
  updateLocationInfo(currentLocation);
  // Check for lava flow and update player health
