#include <vector>
#include <cmath>
class Autoencoder {
public:
    Autoencoder(int input_size, int hidden_size) : 
        input_size_(input_size), hidden_size_(hidden_size),
        W1_(input_size, std::vector<double>(hidden_size)),
        W2_(hidden_size, std::vector<double>(input_size)) {
        // Initialize weights
        for (int i = 0; i < input_size_; i++) {
            for (int j = 0; j < hidden_size_; j++) {
                W1_[i][j] = rand() / double(RAND_MAX);
                W2_[j][i] = rand() / double(RAND_MAX);
            }
        }
    }
    std::vector<double> encode(const std::vector<double>& input) const {
        std::vector<double> hidden(hidden_size_);
        for (int j = 0; j < hidden_size_; j++) {
            double sum = 0.0;
            for (int i = 0; i < input_size_; i++) {
                sum += input[i] * W1_[i][j];
            }
            hidden[j] = 1.0 / (1.0 + exp(-sum));
        }
        return hidden;
    }
    std::vector<double> decode(const std::vector<double>& hidden) const {
        std::vector<double> output(input_size_);
        for (int i = 0; i < input_size_; i++) {
            double sum = 0.0;
            for (int j = 0; j < hidden_size_; j++) {
                sum += hidden[j] * W2_[j][i];
            }
            output[i] = sum;
        }
        return output;
    }
    void train(const std::vector<std::vector<double>>& labeled_data,
               const std::vector<std::vector<double>>& unlabeled_data,
               int num_epochs, double learning_rate) {
        // Train on labeled data
        for (int epoch = 0; epoch < num_epochs; epoch++) {
            for (const auto& input : labeled_data) {
                std::vector<double> hidden = encode(input);
                std::vector<double> output = decode(hidden);
                for (int i = 0; i < input_size_; i++) {
                    for (int j = 0; j < hidden_size_; j++) {
                        W1_[i][j] += learning_rate * (input[i] - output[i]) * output[i] * (1.0 - output[i]) * W2_[j][i] * hidden[j] * (1.0 - hidden[j]);
                        W2_[j][i] += learning_rate * (input[i] - output[i]) * output[i] * (1.0 - output[i]) * hidden[j];
                    }
                }
            }
        }
        // Train on unlabeled data
        for (int epoch = 0; epoch < num_epochs; epoch++) {
            for (const auto& input : unlabeled_data) {
                std::vector<double> hidden = encode(input);
                std::vector<double> output = decode(hidden);
                for (int i = 0; i < input_size_; i++) {
