                        W2_[j][i] += learning_rate * (input[i] - output[i]) * output[i] * (1.0 - output[i]) * hidden[j];
                    }
                }
            }
        }
    }
private:
    int input_size_;
    int hidden_size_;
    std::vector<std::vector<double>> W1_;
    std::vector<std::vector<double>> W2_;
};
