    sendto(sock, message, strlen(message), 0, (sockaddr*)&server_address, sizeof(server_address));
    char buffer[1024] = {0};
    socklen_t len = sizeof(server_address);
    recvfrom(sock, buffer, 1024, 0, (sockaddr*)&server_address, &len);
