Here's an example C++ program that reads a CSV file and calculates the mean, median, mode, and standard deviation of the data:
```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <unordered_map>
using namespace std;
// Function to read a CSV file and return a vector of vectors
vector<vector<double>> read_csv(string filename) {
    // Create a vector of vectors to store the data
    vector<vector<double>> data;
    // Open the file
    ifstream file(filename);
    // Read the file line by line
    string line;
    while (getline(file, line)) {
        // Create a stringstream of the current line
        stringstream ss(line);
        // Create a vector to store the current row
        vector<double> row;
        // Extract each comma-separated value from the line
        string value;
        while (getline(ss, value, ',')) {
            // Convert the value from string to double and add to the row
            row.push_back(stod(value));
        }
        // Add the row to the data vector
        data.push_back(row);
    }
    // Close the file
    file.close();
    return data;
}
// Function to calculate the mean of a vector of numbers
double mean(vector<double> nums) {
    double sum = 0;
    for (double num : nums) {
        sum += num;
    }
    return sum / nums.size();
}
// Function to calculate the median of a vector of numbers
double median(vector<double> nums) {
    sort(nums.begin(), nums.end());
    int n = nums.size();
    if (n % 2 == 0) {
        return (nums[n/2 - 1] + nums[n/2]) / 2;
    } else {
        return nums[n/2];
    }
}
// Function to calculate the mode of a vector of numbers
double mode(vector<double> nums) {
    unordered_map<double, int> freq;
    for (double num : nums) {
        freq[num]++;
    }
    int max_freq = 0;
    double mode = 0;
    for (auto pair : freq) {
        if (pair.second > max_freq) {
            max_freq = pair.second;
            mode = pair.first;
        }
    }
    return mode;
}
// Function to calculate the standard deviation of a vector of numbers
double stdev(vector<double> nums) {
    double avg = mean(nums);
    double sum = 0;
    for (double num : nums) {
        sum += pow(num - avg, 2);
    }
    return sqrt(sum / nums.size());
}
int main() {
    // Read the CSV file into a vector of vectors
    vector<vector<double>> data = read_csv("data.csv");
    // Calculate the mean, median, mode, and standard deviation of each column
