        vector<double> column;
        for (int j = 0; j < data.size(); j++) {
            column.push_back(data[j][i]);
        }
        double column_mean = mean(column);
        double column_median = median(column);
        double column_mode = mode(column);
        double column_stdev = stdev(column);
        cout << "Column " << i+1 << ":\n";
        cout << "Mean: " << column_mean << "\n";
        cout << "Median: " << column_median << "\n";
        cout << "Mode: " << column_mode << "\n";
        cout << "Standard deviation: " << column_stdev << "\n\n";
    }
    return 0;
}
