        else
        {
            targetRotation = Quaternion.Euler(0, closeAngle, 0);
        }
        transform.rotation = Quaternion.Lerp(transform.rotation, targetRotation, Time.deltaTime * (isOpen ? openSpeed : closeSpeed));
    }
    public void Open()
    {
        isOpen = true;
    }
    public void Close()
    {
        isOpen = false;
    }
}
```
This script creates a door object that can be opened and closed by calling the Open and Close methods. The door rotates from its current position to the open or closed position using a Quaternion.Lerp function, which smoothly interpolates between the current and target rotation over time. The open and close speeds and angles can be set in the editor, allowing for customization of the door's behavior.
